 "t19a": "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>q</mi><mi>t</mi></msub><mo stretchy=\"false\">(</mo><msubsup><mi>x</mi><mi>t</mi><mi>i</mi></msubsup><mo>∣</mo><msubsup><mi>x</mi><mn>0</mn><mi>i</mi></msubsup><mo stretchy=\"false\">)</mo><mo>=</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>−</mo><mi>t</mi><mo stretchy=\"false\">)</mo><mtext> </mtext><mn mathvariant=\"bold\">1</mn><mo stretchy=\"false\">[</mo><msubsup><mi>x</mi><mi>t</mi><mi>i</mi></msubsup><mo>=</mo><msubsup><mi>x</mi><mn>0</mn><mi>i</mi></msubsup><mo stretchy=\"false\">]</mo><mo>+</mo><mi>t</mi><mtext> </mtext><mn mathvariant=\"bold\">1</mn><mo stretchy=\"false\">[</mo><msubsup><mi>x</mi><mi>t</mi><mi>i</mi></msubsup><mo>=</mo><mi mathvariant=\"normal\">M</mi><mo stretchy=\"false\">]</mo></mrow><annotation encoding=\"application/x-tex\">q_t(x_t^i\\mid x_0^i)=(1-t)\\,\\mathbf 1[x_t^i=x_0^i]+t\\,\\mathbf 1[x_t^i=\\mathrm M]</annotation></semantics></math>",
 "t19b": "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>L</mi><mo>=</mo><msub><mi mathvariant=\"double-struck\">E</mi><mrow><mi>t</mi><mo separator=\"true\">,</mo><msub><mi>x</mi><mn>0</mn></msub><mo separator=\"true\">,</mo><msub><mi>x</mi><mi>t</mi></msub></mrow></msub><mo fence=\"false\" stretchy=\"true\" minsize=\"1.8em\" maxsize=\"1.8em\">[</mo><mo>−</mo><mfrac><mn>1</mn><mi>t</mi></mfrac><munder><mo>∑</mo><mi>i</mi></munder><mn mathvariant=\"bold\">1</mn><mo stretchy=\"false\">[</mo><msubsup><mi>x</mi><mi>t</mi><mi>i</mi></msubsup><mo>=</mo><mi mathvariant=\"normal\">M</mi><mo stretchy=\"false\">]</mo><mtext> </mtext><mi>log</mi><mo>⁡</mo><msub><mi>p</mi><mi>θ</mi></msub><mo stretchy=\"false\">(</mo><msubsup><mi>x</mi><mn>0</mn><mi>i</mi></msubsup><mo>∣</mo><msub><mi>x</mi><mi>t</mi></msub><mo separator=\"true\">,</mo><mi>t</mi><mo stretchy=\"false\">)</mo><mo fence=\"false\" stretchy=\"true\" minsize=\"1.8em\" maxsize=\"1.8em\">]</mo></mrow><annotation encoding=\"application/x-tex\">L=\\mathbb E_{t,x_0,x_t}\\Big[-\\frac1t\\sum_i\\mathbf 1[x_t^i=\\mathrm M]\\,\\log p_\\theta(x_0^i\\mid x_t,t)\\Big]</annotation></semantics></math>",
 "t20a": "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>q</mi><mo stretchy=\"false\">(</mo><msub><mi>x</mi><mi>t</mi></msub><mo>∣</mo><msub><mi>x</mi><mrow><mi>t</mi><mo>−</mo><mn>1</mn></mrow></msub><mo stretchy=\"false\">)</mo><mo>=</mo><mi mathvariant=\"script\">N</mi><mo fence=\"false\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">(</mo><msqrt><mrow><mn>1</mn><mo>−</mo><msub><mi>β</mi><mi>t</mi></msub></mrow></msqrt><mtext> </mtext><msub><mi>x</mi><mrow><mi>t</mi><mo>−</mo><mn>1</mn></mrow></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>β</mi><mi>t</mi></msub><mi>I</mi><mo fence=\"false\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">)</mo></mrow><annotation encoding=\"application/x-tex\">q(x_t\\mid x_{t-1})=\\mathcal N\\big(\\sqrt{1-\\beta_t}\\,x_{t-1},\\ \\beta_tI\\big)</annotation></semantics></math>",
 "t20b": "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>x</mi><mi>t</mi></msub><mo>=</mo><msqrt><msub><mover accent=\"true\"><mi>α</mi><mo>ˉ</mo></mover><mi>t</mi></msub></msqrt><mtext> </mtext><msub><mi>x</mi><mn>0</mn></msub><mo>+</mo><msqrt><mrow><mn>1</mn><mo>−</mo><msub><mover accent=\"true\"><mi>α</mi><mo>ˉ</mo></mover><mi>t</mi></msub></mrow></msqrt><mtext> </mtext><mi>ε</mi><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mover accent=\"true\"><mi>α</mi><mo>ˉ</mo></mover><mi>t</mi></msub><mo>=</mo><munderover><mo>∏</mo><mrow><mi>s</mi><mo>=</mo><mn>1</mn></mrow><mi>t</mi></munderover><mo stretchy=\"false\">(</mo><mn>1</mn><mo>−</mo><msub><mi>β</mi><mi>s</mi></msub><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">x_t=\\sqrt{\\bar\\alpha_t}\\,x_0+\\sqrt{1-\\bar\\alpha_t}\\,\\varepsilon,\\qquad \\bar\\alpha_t=\\prod_{s=1}^{t}(1-\\beta_s)</annotation></semantics></math>",
 "t20c": "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>L</mi><mrow><mi mathvariant=\"normal\">s</mi><mi mathvariant=\"normal\">i</mi><mi mathvariant=\"normal\">m</mi><mi mathvariant=\"normal\">p</mi><mi mathvariant=\"normal\">l</mi><mi mathvariant=\"normal\">e</mi></mrow></msub><mo>=</mo><mi mathvariant=\"double-struck\">E</mi><mtext> </mtext><mo fence=\"false\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">∥</mo><mi>ε</mi><mo>−</mo><msub><mi>ε</mi><mi>θ</mi></msub><mo stretchy=\"false\">(</mo><msub><mi>x</mi><mi>t</mi></msub><mo separator=\"true\">,</mo><mi>t</mi><mo stretchy=\"false\">)</mo><msup><mo fence=\"false\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">∥</mo><mn>2</mn></msup></mrow><annotation encoding=\"application/x-tex\">L_{\\mathrm{simple}}=\\mathbb E\\,\\big\\|\\varepsilon-\\varepsilon_\\theta(x_t,t)\\big\\|^2</annotation></semantics></math>",
 "t21a": "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>s</mi><mi>t</mi></msub><mo stretchy=\"false\">(</mo><mi>x</mi><mo stretchy=\"false\">)</mo><mo>=</mo><msub><mi mathvariant=\"normal\">∇</mi><mi>x</mi></msub><mi>log</mi><mo>⁡</mo><msub><mi>p</mi><mi>t</mi></msub><mo stretchy=\"false\">(</mo><mi>x</mi><mo stretchy=\"false\">)</mo><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>x</mi><mi>t</mi></msub><mo>=</mo><msub><mi>a</mi><mi>t</mi></msub><msub><mi>x</mi><mn>0</mn></msub><mo>+</mo><msub><mi>σ</mi><mi>t</mi></msub><mi>ε</mi></mrow><annotation encoding=\"application/x-tex\">s_t(x)=\\nabla_x\\log p_t(x),\\qquad x_t=a_tx_0+\\sigma_t\\varepsilon</annotation></semantics></math>",
