 "t25b": "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>v</mi><mo>∗</mo></msub><mo stretchy=\"false\">(</mo><mi>x</mi><mo separator=\"true\">,</mo><mi>t</mi><mo stretchy=\"false\">)</mo><mo>=</mo><mn>2</mn><mo>+</mo><mfrac><mrow><mo>−</mo><mn>1</mn><mo>+</mo><mn>1.25</mn><mtext> </mtext><mi>t</mi></mrow><msub><mi>a</mi><mi>t</mi></msub></mfrac><mtext> </mtext><mo stretchy=\"false\">(</mo><mi>x</mi><mo>−</mo><mn>2</mn><mi>t</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">v_*(x,t)=2+\\frac{-1+1.25\\,t}{a_t}\\,(x-2t)</annotation></semantics></math>",
